      <style>{`
                @keyframes bar-graph {
                    0%, 100% {
                        height: 30%;
                    }
                    25% {
                        height: 70%;
                    }
                    50% {
                        height: 40%;
                    }
                    75% {
                        height: 60%;
                    }
                }

                @keyframes bar-graph-alt {
                    0%, 100% {
                        height: 40%;
                    }
                    25% {
                        height: 60%;
                    }
                    50% {
                        height: 80%;
                    }
                    75% {
                        height: 50%;
                    }
                }

                @keyframes bar-graph-center {
                    0%, 100% {
                        height: 85%;
                    }
                    25% {
                        height: 95%;
                    }
                    50% {
                        height: 75%;
                    }
                    75% {
                        height: 90%;
                    }
                }

                @keyframes float {
                    0%, 100% {
                        transform: translateY(0) rotate(0deg);
                        opacity: 0.7;
                    }
                    33% {
                        transform: translateY(-15px) rotate(5deg);
                        opacity: 0.9;
                    }
                    66% {
                        transform: translateY(-8px) rotate(-5deg);
                        opacity: 0.8;
                    }
                }

                .animate-bar-graph-1 {
                    animation: bar-graph 4s ease-in-out infinite;
                }
                .animate-bar-graph-2 {
                    animation: bar-graph-alt 5s ease-in-out infinite 0.2s;
                }
                .animate-bar-graph-3 {
                    animation: bar-graph 4s ease-in-out infinite 0.4s;
                }
                .animate-bar-graph-4 {
                    animation: bar-graph-alt 5s ease-in-out infinite 0.6s;
                }
                .animate-bar-graph-5 {
                    animation: bar-graph-center 4.5s ease-in-out infinite 0.8s;
                }
                .animate-bar-graph-6 {
                    animation: bar-graph-alt 5s ease-in-out infinite 1s;
                }
                .animate-bar-graph-7 {
                    animation: bar-graph 4s ease-in-out infinite 1.2s;
                }
                .animate-bar-graph-8 {
                    animation: bar-graph-alt 5s ease-in-out infinite 1.4s;
                }
                .animate-bar-graph-9 {
                    animation: bar-graph 4s ease-in-out infinite 1.6s;
                }

                .animate-float-1 {
                    animation: float 6s ease-in-out infinite;
                }
                .animate-float-2 {
                    animation: float 7s ease-in-out infinite 0.5s;
                }
                .animate-float-3 {
                    animation: float 8s ease-in-out infinite 1s;
                }
                .animate-float-4 {
                    animation: float 6.5s ease-in-out infinite 1.5s;
                }
                .animate-float-5 {
                    animation: float 7.5s ease-in-out infinite 2s;
                }
                .animate-float-6 {
                    animation: float 6s ease-in-out infinite 2.5s;
                }
            `}</style>
